  'latency-monitor':i=>{const spans=typedRows(i.spans,[['id',safeKey],['start',int],['end',int]]);if(spans.some(s=>s.end<s.start))fail('耗时不能为负');const durations=spans.map(s=>s.end-s.start).sort((a,b)=>a-b);if(!durations.length)fail('耗时样本不能为空');return {durations,maximum:durations.at(-1),median:durations[Math.floor(durations.length/2)],sumMilliseconds:sum(durations)};},
