  'model-comparison':i=>{const samples=typedRows(i.samples,[['model',text],['correct',int],['total',pos],['latency',int],['cost',int]]);if(samples.some(s=>s.correct>s.total))fail('正确数超过样本数');const criterion=allowed(i.criterion,['accuracy','latency','cost']),ranked=samples.map(s=>({...s,accuracyBasisPoints:Math.floor(s.correct*10000/s.total)})).sort((a,b)=>criterion==='accuracy'?b.accuracyBasisPoints-a.accuracyBasisPoints:a[criterion]-b[criterion]);return {ranked,winner:ranked[0]?.model??null,source:'用户提供的虚构测量样本，未运行真实模型'};},
  'agent-replay':i=>{let value=num(i.initial);const commands=typedRows(i.commands,[['type',v=>allowed(v,['add','multiply'])],['value',num]]),limit=int(i.until);if(limit>commands.length)fail('回放步骤超界');return {states:commands.slice(0,limit).map(c=>{value=c.type==='add'?value+c.value:value*c.value;return value;}),value,replayed:limit};},
